"""Config dict merging."""

import copy


def _copy(value):
    """Return a deep copy of ``value`` so results never share objects."""
    return copy.deepcopy(value)


def deep_merge(base, override):
    """Recursively merge ``override`` into ``base`` and return a new dict.

    Rules:
      * nested dicts are merged recursively instead of being replaced;
      * neither ``base`` nor ``override`` is mutated, and the result does not
        share any nested dict/list object with either input;
      * lists are replaced (not concatenated) by the ``override`` value;
      * when one side holds a dict and the other a non-dict, the ``override``
        value wins;
      * a value of ``None`` in ``override`` removes that key from the result.
    """
    if not isinstance(override, dict):
        # Nothing to merge: the override (if any) simply wins, copied deeply.
        if override is None:
            return {}
        return _copy(override)

    if not isinstance(base, dict):
        base = {}

    result = {key: _copy(value) for key, value in base.items()}

    for key, value in override.items():
        if value is None:
            # An explicit ``None`` deletes the key from the result.
            result.pop(key, None)
            continue
        current = result.get(key)
        if isinstance(current, dict) and isinstance(value, dict):
            result[key] = deep_merge(current, value)
        else:
            result[key] = _copy(value)

    return result
EOF
