import copy
from merge import deep_merge

# 1. nested dicts merged
r = deep_merge({"db": {"host": "a", "port": 1}}, {"db": {"port": 2}})
assert r == {"db": {"host": "a", "port": 2}}, r

# 2. no mutation, no shared nested objects
base = {"db": {"host": "a", "ports": [1, 2]}, "l": [1, 2], "x": {"y": {"z": 1}}}
over = {"db": {"port": 2, "ports": [3]}, "l": [3], "x": {"y": {"w": 9}}}
b0 = copy.deepcopy(base)
o0 = copy.deepcopy(over)
r = deep_merge(base, over)
assert base == b0 and over == o0, (base, over)
def check_no_share(a, b, path=""):
    if isinstance(b, dict):
        assert isinstance(a, dict)
        for k, v in b.items():
            check_no_share(a[k], v, path + "/" + str(k))
    elif isinstance(b, list):
        assert isinstance(a, list)
        assert a is not b, path
        for i, v in enumerate(b):
            check_no_share(a[i], v, path + "/%d" % i)
check_no_share(base, r)
check_no_share(over, r)
assert r is not base and r is not over

# 3. lists replaced
assert deep_merge({"l": [1, 2]}, {"l": [3]}) == {"l": [3]}
assert deep_merge({"l": [1, 2]}, {}) == {"l": [1, 2]}

# 4. dict vs non-dict -> override wins
assert deep_merge({"a": {"b": 1}}, {"a": 5}) == {"a": 5}
assert deep_merge({"a": 5}, {"a": {"b": 1}}) == {"a": {"b": 1}}
assert deep_merge({"a": [1]}, {"a": {"b": 1}}) == {"a": {"b": 1}}

# 5. None deletes key
assert deep_merge({"a": 1, "b": 2}, {"a": None}) == {"b": 2}
assert deep_merge({"a": {"b": 1, "c": 2}}, {"a": {"b": None}}) == {"a": {"c": 2}}
assert deep_merge({"a": {"b": 1}}, {"a": None}) == {}

# 6. arbitrary depth
deep_base = {"a": {"b": {"c": {"d": 1, "e": 2}}}}
deep_over = {"a": {"b": {"c": {"d": 10}, "f": 3}}}
assert deep_merge(deep_base, deep_over) == {"a": {"b": {"c": {"d": 10, "e": 2}, "f": 3}}}

# extra
assert deep_merge({}, {}) == {}
assert deep_merge({"a": 1}, {}) == {"a": 1}
r = deep_merge({"a": 1}, {"a": 1})
assert r == {"a": 1} and r is not base
print("all good")
EOF
